package com.wizzadrds.theworldremembers.voice; import net.fabricmc.fabric.api.networking.v1.PayloadTypeRegistry; import net.fabricmc.fabric.api.networking.v1.ServerPlayNetworking; import net.minecraft.server.level.ServerPlayer; public final class VoiceNetworking{private VoiceNetworking(){}public static void init(){PayloadTypeRegistry.clientboundPlay().register(VoicePacket.TYPE,VoicePacket.CODEC);}public static void send(ServerPlayer p,VoicePacket v){if(ServerPlayNetworking.canSend(p,VoicePacket.TYPE))ServerPlayNetworking.send(p,v);}}